6	export interface PageData {
7	  slug: string;
8	  filename: string;
9	  content: string;
10	  metadata: PageMetadata;
11	}
12	
13	export interface GeneratorOptions {
14	  contentDir: string;
15	  outputDir: string;
16	  templatesDir?: string;
17	  layoutsDir?: string;
18	  partialsDir?: string;
