21	function slugFromFilename(filename: string): string {
22	  return filename.replace(/\.md$/, '');
23	}
24	
25	function generatePageHtml(page: PageData, templateEngine: TemplateEngine | null): string {
26	  const title = page.metadata.title || page.slug;
27	  const layoutName = page.metadata.layout || 'default.hbs';
28	
29	  if (!templateEngine) {
30	    const date = page.metadata.date ? `<p class="date">${page.metadata.date}</p>` : '';
31	    const tags = page.metadata.tags && page.metadata.tags.length > 0
32	      ? `<div class="tags">${page.metadata.tags.map(tag => `<span class="tag">${tag}</span>`).join('')}</div>`
33	      : '';
34	
35	    return `<!DOCTYPE html>
36	<html lang="en">
37	<head>
38	  <meta charset="UTF-8">
39	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
40	  <title>${escapeHtml(title)}</title>
41	  <style>
42	    body { font-family: sans-serif; line-height: 1.6; max-width: 800px; margin: 0 auto; padding: 20px; }
43	    a { color: #0066cc; }
44	    .date { color: #666; font-size: 0.9em; }
45	    .tags { margin: 10px 0; }
46	    .tag { display: inline-block; background: #f0f0f0; padding: 2px 8px; margin: 2px; border-radius: 3px; font-size: 0.9em; }
47	    nav { border-bottom: 1px solid #ddd; margin-bottom: 20px; padding-bottom: 10px; }
48	  </style>
49	</head>
50	<body>
51	  <nav>
52	    <a href="index.html">← Home</a>
53	  </nav>
54	  <article>
55	    <h1>${escapeHtml(title)}</h1>
56	    ${date}
57	    ${tags}
58	    <div class="content">
59	      ${page.content}
60	    </div>
61	  </article>
62	</body>
63	</html>`;
64	  }
65	
66	  return templateEngine.renderWithLayout(page.content, layoutName, {
67	    title: title,
68	    date: page.metadata.date,
69	    tags: page.metadata.tags || [],
70	    slug: page.slug,
71	    ...page.metadata
72	  });
73	}
74	
75	function generateIndexHtml(pages: PageData[], templateEngine: TemplateEngine | null): string {
76	  const sortedPages = pages.sort((a, b) => {
77	    const dateA = new Date(a.metadata.date || '').getTime();
78	    const dateB = new Date(b.metadata.date || '').getTime();
79	    return dateB - dateA;
80	  });
81	
82	  if (!templateEngine) {
83	    const pageLinks = sortedPages
84	      .map(page => {
85	        const title = page.metadata.title || page.slug;
86	        const dateStr = page.metadata.date ? ` (${page.metadata.date})` : '';
87	        return `<li><a href="${page.slug}.html">${escapeHtml(title)}</a>${dateStr}</li>`;
88	      })
89	      .join('\n    ');
90	
91	    return `<!DOCTYPE html>
92	<html lang="en">
93	<head>
94	  <meta charset="UTF-8">
95	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
96	  <title>Home</title>
97	  <style>
98	    body { font-family: sans-serif; line-height: 1.6; max-width: 800px; margin: 0 auto; padding: 20px; }
99	    a { color: #0066cc; }
100	    li { margin: 8px 0; }
101	  </style>
102	</head>
103	<body>
104	  <h1>Pages</h1>
105	  <ul>
106	    ${pageLinks}
107	  </ul>
108	</body>
109	</html>`;
110	  }
111	
112	  const pageList = sortedPages.map(page => ({
113	    title: page.metadata.title || page.slug,
114	    slug: page.slug,
115	    date: page.metadata.date
116	  }));
117	
118	  return templateEngine.render('index.hbs', 'index.hbs', { pages: pageList });
119	}
