121	function escapeHtml(text: string): string {
122	  const map: Record<string, string> = {
123	    '&': '&amp;',
124	    '<': '&lt;',
125	    '>': '&gt;',
126	    '"': '&quot;',
127	    "'": '&#039;'
128	  };
129	  return text.replace(/[&<>"']/g, char => map[char]);
130	}
