132	export async function generate(options: GeneratorOptions): Promise<void> {
133	  const { contentDir, outputDir } = options;
134	  const templatesDir = options.templatesDir || './templates';
135	  const layoutsDir = options.layoutsDir || './templates/layouts';
136	  const partialsDir = options.partialsDir || './templates/partials';
137	
138	  if (!fs.existsSync(contentDir)) {
139	    throw new Error(`Content directory not found: ${contentDir}`);
140	  }
141	
142	  if (!fs.existsSync(outputDir)) {
143	    fs.mkdirSync(outputDir, { recursive: true });
144	  }
145	
146	  let templateEngine: TemplateEngine | null = null;
147	
148	  if (fs.existsSync(templatesDir)) {
149	    ensureDefaultTemplates(templatesDir, layoutsDir, partialsDir);
150	    templateEngine = new TemplateEngine({
151	      templatesDir,
152	      layoutsDir,
153	      partialsDir
154	    });
155	  }
156	
157	  const files = fs.readdirSync(contentDir).filter(file => file.endsWith('.md'));
158	
159	  if (files.length === 0) {
160	    throw new Error(`No markdown files found in ${contentDir}`);
161	  }
162	
163	  const pages: PageData[] = [];
164	
165	  for (const file of files) {
166	    const filePath = path.join(contentDir, file);
167	    const content = fs.readFileSync(filePath, 'utf-8');
168	    const parsed = await parseMarkdownWithYaml(content);
169	
170	    const page: PageData = {
171	      slug: slugFromFilename(file),
172	      filename: file,
173	      content: parsed.content,
174	      metadata: parsed.metadata
175	    };
176	
177	    pages.push(page);
178	
179	    const pageHtml = generatePageHtml(page, templateEngine);
180	    const outputPath = path.join(outputDir, `${page.slug}.html`);
181	    fs.writeFileSync(outputPath, pageHtml, 'utf-8');
182	  }
183	
184	  const indexHtml = generateIndexHtml(pages, templateEngine);
185	  const indexPath = path.join(outputDir, 'index.html');
186	  fs.writeFileSync(indexPath, indexHtml, 'utf-8');
187	
188	  console.log(`Generated site with ${pages.length} page(s) in ${outputDir}`);
189	}
