191	function ensureDefaultTemplates(templatesDir: string, layoutsDir: string, partialsDir: string): void {
192	  if (!fs.existsSync(templatesDir)) {
193	    fs.mkdirSync(templatesDir, { recursive: true });
194	  }
195	  if (!fs.existsSync(layoutsDir)) {
196	    fs.mkdirSync(layoutsDir, { recursive: true });
197	  }
198	  if (!fs.existsSync(partialsDir)) {
199	    fs.mkdirSync(partialsDir, { recursive: true });
200	  }
201	
202	  const defaultLayoutPath = path.join(layoutsDir, 'default.hbs');
203	  if (!fs.existsSync(defaultLayoutPath)) {
204	    fs.writeFileSync(defaultLayoutPath, createDefaultLayout(), 'utf-8');
205	  }
206	
207	  const indexLayoutPath = path.join(layoutsDir, 'index.hbs');
208	  if (!fs.existsSync(indexLayoutPath)) {
209	    fs.writeFileSync(indexLayoutPath, createDefaultIndexLayout(), 'utf-8');
210	  }
211	
212	  const indexTemplatePath = path.join(templatesDir, 'index.hbs');
213	  if (!fs.existsSync(indexTemplatePath)) {
214	    fs.writeFileSync(indexTemplatePath, '{{{body}}}', 'utf-8');
215	  }
216	
217	  const navPartialPath = path.join(partialsDir, 'nav.hbs');
218	  if (!fs.existsSync(navPartialPath)) {
219	    fs.writeFileSync(navPartialPath, createDefaultNavPartial(), 'utf-8');
220	  }
221	}
