1	import fs from 'fs';
2	import path from 'path';
3	import Handlebars from 'handlebars';
4	
5	export interface TemplateEngineOptions {
6	  templatesDir: string;
7	  layoutsDir: string;
8	  partialsDir: string;
9	}
10	
11	export class TemplateEngine {
12	  private templatesDir: string;
13	  private layoutsDir: string;
14	  private partialsDir: string;
15	  private cache: Map<string, HandlebarsTemplateDelegate> = new Map();
16	
17	  constructor(options: TemplateEngineOptions) {
18	    this.templatesDir = options.templatesDir;
19	    this.layoutsDir = options.layoutsDir;
20	    this.partialsDir = options.partialsDir;
21	
22	    this.registerPartials();
23	  }
24	
25	  private registerPartials(): void {
26	    if (!fs.existsSync(this.partialsDir)) {
27	      return;
28	    }
29	
30	    const files = fs.readdirSync(this.partialsDir).filter(file => file.endsWith('.hbs'));
31	
32	    for (const file of files) {
33	      const filePath = path.join(this.partialsDir, file);
34	      const content = fs.readFileSync(filePath, 'utf-8');
35	      const partialName = file.replace(/\.hbs$/, '');
36	      Handlebars.registerPartial(partialName, content);
37	    }
38	  }
39	
40	  private getTemplate(filename: string): HandlebarsTemplateDelegate {
41	    if (this.cache.has(filename)) {
42	      return this.cache.get(filename)!;
43	    }
44	
45	    const filePath = path.join(this.templatesDir, filename);
46	    if (!fs.existsSync(filePath)) {
47	      throw new Error(`Template not found: ${filename}`);
48	    }
49	
50	    const content = fs.readFileSync(filePath, 'utf-8');
51	    const template = Handlebars.compile(content);
52	    this.cache.set(filename, template);
53	    return template;
54	  }
55	
56	  private getLayout(layoutName: string): HandlebarsTemplateDelegate {
57	    return this.getTemplate(`layouts/${layoutName}`);
58	  }
59	
60	  render(templateName: string, layoutName: string | undefined, data: any): string {
61	    const template = this.getTemplate(templateName);
62	    const renderedContent = template(data);
63	
64	    if (!layoutName) {
65	      return renderedContent;
66	    }
67	
68	    const layout = this.getLayout(layoutName);
69	    return layout({
70	      ...data,
71	      body: renderedContent
72	    });
73	  }
74	
75	  renderWithLayout(content: string, layoutName: string | undefined, data: any): string {
76	    if (!layoutName) {
77	      return content;
78	    }
79	
80	    const layout = this.getLayout(layoutName);
81	    return layout({
82	      ...data,
83	      body: content
84	    });
85	  }
86	}
