1	import http from 'http';
2	import fs from 'fs';
3	import path from 'path';
4	import { fileURLToPath } from 'url';
5	import { WebSocketServer } from 'ws';
6	import chokidar from 'chokidar';
7	import { generate } from './generator.js';
8	
9	const __filename = fileURLToPath(import.meta.url);
10	const __dirname = path.dirname(__filename);
11	
12	export interface ServeOptions {
13	  contentDir: string;
14	  outputDir: string;
15	  port?: number;
16	  templatesDir?: string;
17	  layoutsDir?: string;
18	  partialsDir?: string;
19	}
20	
21	const LIVE_RELOAD_SCRIPT = `
22	<script>
23	(function() {
24	  const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
25	  const ws = new WebSocket(protocol + '//' + window.location.host + '/__live-reload__');
26	
27	  ws.onmessage = function(event) {
28	    if (event.data === 'reload') {
29	      window.location.reload();
30	    }
31	  };
32	
33	  ws.onclose = function() {
34	    setTimeout(function() {
35	      window.location.reload();
36	    }, 1000);
37	  };
38	})();
39	</script>
40	`;
41	
42	export interface ServeResult {
43	  close: () => Promise<void>;
44	}
45	
46	export async function serve(options: ServeOptions, test?: boolean): Promise<ServeResult> {
47	  const port = options.port || 3000;
48	  const { contentDir, outputDir } = options;
49	  const templatesDir = options.templatesDir || './templates';
50	  const layoutsDir = options.layoutsDir || './templates/layouts';
51	  const partialsDir = options.partialsDir || './templates/partials';
52	
53	  let isRebuilding = false;
54	  const clients: Set<any> = new Set();
55	
56	  const rebuildSite = async () => {
57	    if (isRebuilding) return;
58	    isRebuilding = true;
59	
60	    try {
61	      await generate({
62	        contentDir,
63	        outputDir,
64	        templatesDir,
65	        layoutsDir,
66	        partialsDir
67	      });
68	      console.log('Site rebuilt successfully');
69	
70	      clients.forEach(client => {
71	        if (client.readyState === 1) {
72	          client.send('reload');
73	        }
74	      });
75	    } catch (error) {
76	      console.error('Error rebuilding site:', error instanceof Error ? error.message : error);
77	    } finally {
78	      isRebuilding = false;
79	    }
80	  };
81	
82	  const server = http.createServer((req, res) => {
83	    if (req.url === '/__live-reload__') {
84	      res.writeHead(404);
85	      res.end();
86	      return;
87	    }
88	
89	    let filePath = path.join(outputDir, req.url === '/' ? 'index.html' : req.url);
90	
91	    if (filePath.endsWith('/')) {
92	      filePath = path.join(filePath, 'index.html');
93	    }
94	
95	    if (!fs.existsSync(filePath)) {
96	      res.writeHead(404);
97	      res.end('Not Found');
98	      return;
99	    }
100	
101	    let content = fs.readFileSync(filePath, 'utf-8');
102	
103	    if (filePath.endsWith('.html')) {
104	      content = content.replace('</body>', LIVE_RELOAD_SCRIPT + '</body>');
105	    }
106	
107	    const ext = path.extname(filePath);
108	    const mimeTypes: Record<string, string> = {
109	      '.html': 'text/html',
110	      '.css': 'text/css',
111	      '.js': 'application/javascript',
112	      '.json': 'application/json',
113	      '.png': 'image/png',
114	      '.jpg': 'image/jpeg',
115	      '.gif': 'image/gif',
116	      '.svg': 'image/svg+xml'
117	    };
118	
119	    const contentType = mimeTypes[ext] || 'text/plain';
120	    res.writeHead(200, { 'Content-Type': contentType });
121	    res.end(content);
122	  });
123	
124	  const wss = new WebSocketServer({ server });
125	
126	  wss.on('connection', (ws) => {
127	    clients.add(ws);
128	
129	    ws.on('close', () => {
130	      clients.delete(ws);
131	    });
132	  });
133	
134	  const watcher = chokidar.watch([contentDir, templatesDir], {
135	    ignored: /(^|[/\\])\.|node_modules/,
136	    persistent: true,
137	    awaitWriteFinish: {
138	      stabilityThreshold: 100,
139	      pollInterval: 100
140	    }
141	  });
142	
143	  watcher.on('change', () => {
144	    rebuildSite();
145	  });
146	
147	  watcher.on('add', () => {
148	    rebuildSite();
149	  });
150	
151	  watcher.on('unlink', () => {
152	    rebuildSite();
153	  });
154	
155	  await new Promise<void>(resolve => {
156	    server.listen(port, () => {
157	      if (!test) {
158	        console.log(`Dev server running at http://localhost:${port}`);
159	        console.log(`Watching ${contentDir} and ${templatesDir} for changes`);
160	      }
161	      resolve();
162	    });
163	  });
164	
165	  if (!test) {
166	    process.on('SIGINT', () => {
167	      console.log('\nShutting down...');
168	      watcher.close();
169	      server.close();
170	      process.exit(0);
171	    });
172	  }
173	
174	  return {
175	    close: async () => {
176	      await new Promise<void>(resolve => {
177	        watcher.close();
178	        server.close(() => resolve());
179	      });
180	    }
181	  };
182	}
