      const ext = path.extname(filePath);
      const mimeTypes: Record<string, string> = {
        '.html': 'text/html',
        '.css': 'text/css',
        '.js': 'application/javascript',
        '.json': 'application/json',
        '.png': 'image/png',
        '.jpg': 'image/jpeg',
        '.gif': 'image/gif',
        '.svg': 'image/svg+xml'
      };

      const contentType = mimeTypes[ext] || 'text/plain';
      res.writeHead(200, { 'Content-Type': contentType });
      res.end(content);
    });

    this.wss = new WebSocketServer({ server: this.server });

    this.wss.on('connection', (ws) => {
      this.clients.add(ws);

      ws.on('close', () => {
        this.clients.delete(ws);
      });
    });

    this.watcher = chokidar.watch([contentDir, templatesDir], {
      ignored: /(^|[/\\])\.|node_modules/,
      persistent: true,
      awaitWriteFinish: {
        stabilityThreshold: 100,
        pollInterval: 100
      }
    });

    this.watcher.on('change', () => {
      rebuildSite();
    });

    this.watcher.on('add', () => {
      rebuildSite();
    });

    this.watcher.on('unlink', () => {
      rebuildSite();
    });

    await new Promise<void>(resolve => {
      this.server!.listen(this.port, () => {
        console.log(`Dev server running at http://localhost:${this.port}`);
        console.log(`Watching ${contentDir} and ${templatesDir} for changes`);
        resolve();
      });
    });

    process.on('SIGINT', () => {
      console.log('\nShutting down...');
      this.watcher.close();
      this.server!.close();
      process.exit(0);
    });
  }

  async onEnd(context: BuildContext): Promise<void> {
    if (this.watcher) {
      this.watcher.close();
    }
    if (this.server) {
      await new Promise<void>(resolve => {
        this.server!.close(() => resolve());
      });
    }
  }
